                    y,x=st.pop()
                    if (y,x) in comp: continue
                    comp.add((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx]==g[y][x] and not seen[ny][nx]:
                                seen[ny][nx]=True; st.append((ny,nx))
                comps.append((g[i][j],comp))
    return comps

