def max_rect_hist(grid,col):
    h=len(grid); w=len(grid[0]); best=0
    heights=[0]*w
    for i in range(h):
        for j in range(w): heights[j]=heights[j]+1 if grid[i][j]==col else 0
        stack=[]
        for j in range(w+1):
            cur=heights[j] if j<w else 0
            while stack and stack[-1]>cur:
