def solve(gin,minarea=4):
    h=len(gin); w=len(gin[0])
    cnt={}
    for r in gin:
        for x in r: cnt[x]=cnt.get(x,0)+1
    bg=max(cnt,key=cnt.get)
    out=[[bg]*w for _ in range(h)]
    for col in cnt:
        if col==bg: continue
        mr=max_rect_hist(gin,col)
        if mr<minarea: continue
        # find actual largest rect location & fill it
        heights=[0]*w
        for i in range(h):
            for j in range(w): heights[j]=heights[j]+1 if gin[i][j]==col else 0
        # find rect achieving max area
        best=(0,0,-1)
        for i in range(h):
            heights=[heights[j]+1 if gin[i][j]==col else 0 for j in range(w)]
            heights.append(0); stack=[]
            for j in range(len(heights)):
                while stack and stack[-1][0]>=heights[j]:
                    _,prev_h=stack.pop()
                    width=j-stack[-1][1]-1 if stack else j
                    if prev_h*width>best[0]: best=(prev_h*width,prev_h,j-width)
                stack.append((heights[j],j))
        area,H,span=best
        if area<mr: continue
        i=0
        while i<h:
            heights=[heights[j]+1 if gin[i][j]==col else 0 for j in range(w)]; heights.append(0); stack=[]
            cand=[]
            for j in range(len(heights)):
                while stack and stack[-1][0]>=heights[j]:
                    _,ph=stack.pop()
                    wid=j-1-stack[-1][1]-1 if stack else j-1
                    cand.append((ph*wid, ph, j, stack[-1][1] if stack else -1))
                stack.append((heights[j],j))
            for a_,H_,c_,d_ in sorted(cand,reverse=True):
                if a_==area:
                    r0=i-H_+1; r1=i
                    for yy in range(r0,r1+1):
                        for xx in range(c_,d_+1):
                            if gin[yy][xx]==col: out[yy][xx]=col
                    break
        i+=1
    return out
